Request: New page: a color name game. A box shows a random color out of red, blue, green, yellow, and there are 4 buttons with those names. Right answer +1 point and a new color; wrong answer shows 'Nope!'.

```html
<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>Color game</title>
  <style>
    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #ffffff; color: #1f2937; text-align: center; }
    button { font: inherit; font-weight: 700; padding: 10px 18px; margin: 4px; border: 0; border-radius: 10px; background: #ffc93c; color: #1c1405; cursor: pointer; }
    .box { display: flex; flex-direction: column; gap: 8px; padding: 12px; margin: 8px 0; border-radius: 12px; align-items: center; }
    .box.row { flex-direction: row; flex-wrap: wrap; align-items: center; justify-content: center; }
  </style>
</head>
<body>
  <div id="swatch" class="box" style="background:#ef4444">
    <h1 id="q">?</h1>
  </div>
  <div id="btns" class="box row">
    <button id="b1">red</button>
    <button id="b2">blue</button>
    <button id="b3">green</button>
    <button id="b4">yellow</button>
  </div>
  <h3 id="scoreText">Score: 0</h3>
  <script>
    var k, ans, cols, score;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    // 이 함수를 설명하세요...
    function newColor() {
      ans = mathRandomInt(1, 4);
      document.getElementById("swatch").style.background = cols[(ans - 1)];
    }

    // 이 함수를 설명하세요...
    function guess(k) {
      if (k == ans) {
        score = (typeof score === 'number' ? score : 0) + 1;
        document.getElementById("scoreText").textContent = 'Score: ' + String(score);
        newColor();
      } else {
        document.getElementById("scoreText").textContent = 'Nope!';
      }
    }

    document.getElementById("b1").addEventListener('click', function () {
      guess(1);
    });
    document.getElementById("b2").addEventListener('click', function () {
      guess(2);
    });
    document.getElementById("b3").addEventListener('click', function () {
      guess(3);
    });
    document.getElementById("b4").addEventListener('click', function () {
      guess(4);
    });

    cols = ["#ef4444", "#3b82f6", "#22c55e", "#facc15"];
    score = 0;
    newColor();
  </script>
</body>
</html>
```

```html
<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>Book reviews</title>
  <style>
    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #fff8e1; color: #1f2937; text-align: center; }
    button { font: inherit; font-weight: 700; padding: 10px 18px; margin: 4px; border: 0; border-radius: 10px; background: #ffc93c; color: #1c1405; cursor: pointer; }
    input { font: inherit; padding: 9px 12px; margin: 4px; border: 1px solid #9ca3af; border-radius: 9px; }
    ul { display: inline-block; text-align: left; }
  </style>
</head>
<body>
  <input id="book" type="text" placeholder="Book name">
  <input id="stars" type="number" placeholder="Stars 1-5">
  <button id="add">Add</button>
  <ul id="list"></ul>
  <p id="avg">Average: -</p>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var sum, k, n, st;

    document.getElementById("add").addEventListener('click', function () {
      k = Math.min(Math.max((parseFloat(document.getElementById("stars").value) || 0), 1), 5);
      st = '';
      for (var count = 0; count < k; count++) {
        st = String(st) + '★';
      }
      __add("list", ['📘 ',document.getElementById("book").value,' ',st].join(''));
      sum = (typeof sum === 'number' ? sum : 0) + k;
      n = (typeof n === 'number' ? n : 0) + 1;
      document.getElementById("avg").textContent = ['Average: ',Math.round((sum / n) * 10) / 10,' ★'].join('');
    });

    sum = 0;
    n = 0;
  </script>
</body>
</html>
