</head>
<body>
  <h1 id="count">0</h1>
  <button id="plus">누르기</button>
  <button id="reset">리셋</button>
  <p id="hint">버튼을 눌러 보세요</p>
  <script>
    var n;

    document.getElementById("plus").addEventListener('click', function () {
      n = (typeof n === 'number' ? n : 0) + 1;
