```html
<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>두더지 잡기</title>
  <style>
    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #dcfce7; color: #1f2937; text-align: center; }
    button { font: inherit; font-weight: 700; padding: 10px 18px; margin: 4px; border: 0; border-radius: 10px; background: #ffc93c; color: #1c1405; cursor: pointer; }
  </style>
</head>
<body>
  <h1 id="title">🔨 두더지 잡기</h1>
  <h2 id="scoreT">점수 0</h2>
  <button id="go">30초 게임 시작</button>
  <button id="mole">🐹</button>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __size(name, prop, v) {
      var s = $(name).style;
      if (prop === 'opacity') s.opacity = v / 100;
      else if (prop === 'rotate') s.transform = 'rotate(' + v + 'deg)';
      else s[prop] = v + 'px';
    }
    function __move(name, x, y) {
      var s = $(name).style;
      s.position = 'absolute';
      s.left = x + 'px';
      s.top = y + 'px';
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }
    var __timers = [];
    var __audio;
    function __beep(freq, sec) {
      __audio = __audio || new (window.AudioContext || window.webkitAudioContext)();
      var o = __audio.createOscillator(), g = __audio.createGain(), t = __audio.currentTime;
      o.frequency.value = freq;
      o.connect(g); g.connect(__audio.destination);
      g.gain.setValueAtTime(0.2, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + sec);
      o.start(t); o.stop(t + sec);
    }

    var score;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("go").addEventListener('click', function () {
      score = 0;
      document.getElementById("scoreT").textContent = '점수 0';
      __show("go", "hide");
      __show("mole", "show");
      setTimeout(function () {
        __show("mole", "hide");
        __show("go", "show");
        document.getElementById("scoreT").textContent = '끝! 최종 점수 ' + String(score);
      }, (30) * 1000);
    });
    __timers.push(setInterval(function () {
      __move("mole", mathRandomInt(20, 300), mathRandomInt(150, 450));
    }, 800));
    document.getElementById("mole").addEventListener('click', function () {
      score = (typeof score === 'number' ? score : 0) + 1;
      document.getElementById("scoreT").textContent = '점수 ' + String(score);
      __beep(523.25, 0.08);
      __move("mole", mathRandomInt(20, 300), mathRandomInt(150, 450));
    });

    __show("mole", "hide");
    __size("mole", "fontSize", 40);
  </script>
</body>
</html>
```

