  </style>
</head>
<body>
  <h2 id="title1">Draw with the arrow keys, Enter clears</h2>
  <canvas id="board" width="300" height="300"></canvas>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __pen(name) { return $(name).getContext('2d'); }
    function __clear(name) { var c = $(name); __pen(name).clearRect(0, 0, c.width, c.height); }
    function __circle(name, x, y, r, color) { var g = __pen(name); g.fillStyle = color; g.beginPath(); g.arc(x, y, Math.max(0, r), 0, Math.PI * 2); g.fill(); }

    var x, y;

    // 이 함수를 설명하세요...
    function draw() {
      x = Math.min(Math.max(x, 4), 296);
      y = Math.min(Math.max(y, 4), 296);
      __circle("board", x, y, 4, "#111111");
    }

    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowUp") {
        e.preventDefault();
        y = (typeof y === 'number' ? y : 0) + -6;
        draw();
      }
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowDown") {
        e.preventDefault();
        y = (typeof y === 'number' ? y : 0) + 6;
        draw();
      }
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowLeft") {
        e.preventDefault();
        x = (typeof x === 'number' ? x : 0) + -6;
        draw();
      }
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "ArrowRight") {
        e.preventDefault();
        x = (typeof x === 'number' ? x : 0) + 6;
        draw();
      }
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === "Enter") {
        e.preventDefault();
        __clear("board");
        draw();
      }
    });

    x = 150;
    y = 150;
    draw();
  </script>
</body>
</html>
