    var answer, tries;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("checkBtn").addEventListener('click', function () {
      tries = (typeof tries === 'number' ? tries : 0) + 1;
      if ((parseFloat(document.getElementById("guessIn").value) || 0) == answer) {
        document.getElementById("result").textContent = '正解! 回数: ' + String(tries);
      } else if ((parseFloat(document.getElementById("guessIn").value) || 0) < answer) {
        document.getElementById("result").textContent = 'もっと大きい ⬆';
      } else {
        document.getElementById("result").textContent = 'もっと小さい ⬇';
