  <h1 id="title1">Primzahlen bis 50</h1>
  <button id="showBtn">Anzeigen</button>
  <ul id="primeList"></ul>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var cnt, n;

    function mathIsPrime(n) {
      // https://en.wikipedia.org/wiki/Primality_test#Naive_methods
      if (n == 2 || n == 3) {
        return true;
      }
      // False if n is NaN, negative, is 1, or not whole.
      // And false if n is divisible by 2 or 3.
      if (isNaN(n) || n <= 1 || n % 1 !== 0 || n % 2 === 0 || n % 3 === 0) {
        return false;
      }
      // Check all the numbers of form 6k +/- 1, up to sqrt(n).
      for (var x = 6; x <= Math.sqrt(n) + 1; x += 6) {
        if (n % (x - 1) === 0 || n % (x + 1) === 0) {
          return false;
        }
      }
      return true;
    }

    document.getElementById("showBtn").addEventListener('click', function () {
      document.getElementById("primeList").textContent = '';
      cnt = 0;
      for (n = 2; n <= 50; n++) {
        if (mathIsPrime(n)) {
          __add("primeList", n);
          cnt = (typeof cnt === 'number' ? cnt : 0) + 1;
        }
      }
    });
  </script>
</body>
