  <h1 id="diceText">🎲 - 🎲</h1>
  <button id="rollBtn">Roll</button>
  <h3 id="msg"></h3>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }

    var me, a, cpu, b;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("rollBtn").addEventListener('click', function () {
      a = mathRandomInt(1, 6);
      b = mathRandomInt(1, 6);
      document.getElementById("diceText").textContent = [a,' - ',b].join('');
      if (a > b) {
        me = (typeof me === 'number' ? me : 0) + 1;
      } else if (b > a) {
        cpu = (typeof cpu === 'number' ? cpu : 0) + 1;
      }
      document.getElementById("scoreText").textContent = ['You ',me,' : ',cpu,' CPU'].join('');
      if (me >= 5) {
        document.getElementById("msg").textContent = 'You win the match! 🏆';
        __show("rollBtn", "hide");
      } else if (cpu >= 5) {
        document.getElementById("msg").textContent = 'CPU wins the match';
        __show("rollBtn", "hide");
      }
    });

    me = 0;
    cpu = 0;
  </script>
</body>
</html>
