  </style>
</head>
<body>
  <h1 id="t">Random teams</h1>
  <div id="r" class="box row">
    <input id="nm" type="text" placeholder="Name">
    <button id="add">Add</button>
  </div>
  <ul id="all"></ul>
  <button id="make">Make teams</button>
  <div id="teams" class="box row">
    <div id="c1" class="box">
      <h2 id="h1">Team 1</h2>
      <ul id="t1"></ul>
    </div>
    <div id="c2" class="box">
      <h2 id="h2">Team 2</h2>
      <ul id="t2"></ul>
    </div>
  </div>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __add(name, value) {
      var el = $(name);
      if (el.tagName === 'UL') {
        var li = document.createElement('li');
        li.textContent = value;
        el.appendChild(li);
      } else if (el.tagName === 'INPUT') el.value += value;
      else el.textContent += value;
    }

    var names, pool, i, p;

    function listsGetSortCompare(type, direction) {
      var compareFuncs = {
        'NUMERIC': function(a, b) {
            return Number(a) - Number(b); },
        'TEXT': function(a, b) {
            return String(a) > String(b) ? 1 : -1; },
        'IGNORE_CASE': function(a, b) {
            return String(a).toLowerCase() > String(b).toLowerCase() ? 1 : -1; },
      };
      var compare = compareFuncs[type];
      return function(a, b) { return compare(a, b) * direction; };
    }

    function listsGetRandomItem(list, remove) {
      var x = Math.floor(Math.random() * list.length);
      if (remove) {
        return list.splice(x, 1)[0];
      } else {
        return list[x];
      }
    }

    document.getElementById("add").addEventListener('click', function () {
      if (!!document.getElementById("nm").value.length) {
        names.push(document.getElementById("nm").value);
        __add("all", document.getElementById("nm").value);
      }
      document.getElementById("nm").value = '';
    });
    document.getElementById("make").addEventListener('click', function () {
      document.getElementById("t1").textContent = '';
      document.getElementById("t2").textContent = '';
      pool = names.slice().sort(listsGetSortCompare("TEXT", 1));
      i = 0;
      while (!!pool.length) {
        p = listsGetRandomItem(pool, true);
        if (i % 2 == 0) {
          __add("t1", p);
        } else {
          __add("t2", p);
        }
        i = (typeof i === 'number' ? i : 0) + 1;
      }
    });

    names = [];
  </script>
</body>
</html>
