  </style>
</head>
<body>
  <button id="startBtn">시작</button>
  <h1 id="msg"></h1>
  <script>
    var __timers = [];

    var s, ms;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("startBtn").addEventListener('click', function () {
      s = 1;
      ms = 0;
      document.getElementById("msg").textContent = '기다려...';
      setTimeout(function () {
        if (s == 1) {
          s = 2;
          document.getElementById("msg").textContent = '지금! 스페이스!';
        }
      }, (mathRandomInt(2, 5)) * 1000);
    });
    __timers.push(setInterval(function () {
      if (s == 2) {
        ms = (typeof ms === 'number' ? ms : 0) + 20;
      }
    }, 20));
    document.addEventListener('keydown', function (e) {
      if (e.key === " ") {
        e.preventDefault();
        if (s == 1) {
          s = 0;
          document.getElementById("msg").textContent = '너무 빨라요! 다시!';
        } else if (s == 2) {
          s = 0;
          document.getElementById("msg").textContent = '기록(ms): ' + String(ms);
        }
      }
    });

    s = 0;
  </script>
</body>
